from research_helpers import *
base='https://www.nhkspg.co.jp/en/products/'
ps=[];es=[]
for name,path,desc in [('NHK Spring stage heaters','semiconductor/stage-heater','Custom stage heaters for multizone temperature control in semiconductor deposition equipment.'),('NHK Spring aluminum cooling plates','semiconductor/cooling-plate','Aluminum cooling plates for semiconductor electrostatic chucks.'),('NHK Spring titanium cooling plates','semiconductor/cooling-plate','Titanium cooling plates combining diffusion bonding and ceramic thermal spraying for semiconductor electrostatic chucks.'),('NHK Spring shower heads','semiconductor/shower-head','Precision gas-distribution shower heads for deposition and etching equipment.')]:
 e=ev(base+path,'Current manufacturer product detail confirms identity, use and custom manufacture; no public exact catalogue part number.');es.append(e);ps.append(p(name,desc,e,'commercial',roles=['developer','manufacturer'],typ='product',sector='semiconductors',sub='semiconductor_equipment',attributes={'offering_scope':'custom product family'}))
M=ev(base+'industry/telecommunications/semiconductor','Current manufacturer lists four distinct microcontactor series and final-test sockets for semiconductor inspection.')
for code,feature in [('SCP','low-resistance coiled contact probes'),('HCP','electrically stable contact probes'),('NIC','high-frequency contact probes'),('AZT','contact-position accuracy')]:
 ps.append(p('NHK Spring '+code+' microcontactors','Semiconductor inspection contact-probe family; '+feature+'.',M,'commercial',roles=['developer','manufacturer'],typ='product',sector='semiconductors',sub='semiconductor_equipment',attributes={'series':code}))
ps.append(p('NHK Spring semiconductor test sockets','Final-test inspection sockets for packaged semiconductor devices.',M,'commercial',roles=['manufacturer'],typ='product',sector='semiconductors',sub='semiconductor_equipment'))
C=ev(base+'spring/springmechanism/ceramicspring','Current ceramic coil springs explicitly used in semiconductor equipment and high-temperature/vacuum environments.')
ps.append(p('NHK Spring ceramic springs','Nonmetallic coil springs for high-temperature and semiconductor equipment applications.',C,'commercial',roles=['developer','manufacturer'],typ='product',sector='semiconductors',sub='semiconductor_equipment'))
R=ev(base+'spring/springmechanism','Robot-arm torque-assist springs manufactured by group subsidiary SUMIHATSU; parent represented as commercial partner.')
ps.append(p('SUMIHATSU robot-arm assist springs','Spring components reducing motor torque requirements in robot arms.',R,'commercial',roles=['commercial_partner'],typ='product',sector='robotics',sub='autonomy_and_components',attributes={'manufacturer':'SUMIHATSU Co., Ltd.'}))
A=ev(base+'spring/springmechanism/accumulator','Manufacturer explicitly describes energy storage by metal-bellows hydraulic accumulator; not a chemical battery.')
ps.append(p('NHK Spring metal bellows accumulators','Hydraulic pressure vessels storing energy with nitrogen gas separated from liquid by welded metal bellows.',A,'commercial',roles=['developer','manufacturer'],typ='product',sector='energy_storage',sub='mechanical_storage'))
I=ev('https://www.nhkspg.co.jp/hubfs/nhkspg.co.jp/en/pdf/news/management_business/2026/20260115_en.pdf','January2026 issuer announcement: resin-insulated metal substrate for EV traction power modules in actual mass production since December2024; Denso inverter is customer product, not NHK inverter.')
ps.append(p('NHK Spring resin-insulated metal substrate for traction power modules','Integrated metal substrate using high-thermal-dissipation resin insulation for power semiconductor modules.',I,'commercial',roles=['developer','manufacturer'],typ='product',sector='semiconductors',sub='materials_and_packaging',attributes={'mass_production_started':'2024-12','insulating_sheet_supplier':'Sumitomo Bakelite','customer_application':'Denso traction-inverter power module'}))
cs=[company('NHK Spring Co. Ltd',ps,es+[M,C,R,A,I],'Thirteen distinct semiconductor, robotic-component and mechanical-storage offerings reviewed. Exact probe/socket part numbers, other metal substrate products, ceramic equipment parts and full subsidiary product range remain to research; no HDD mechanics misclassified as semiconductor chips.')]
D=ev('https://www.dbi-ag.de/unternehmen/unternehmensprofil/','Current company profile: March2026 liquidation resolution; remaining Adrenomed minority holding for sale, other holdings sold2025/26 or written off. Portfolio investee products are not automatically DBI-owned/developed products.')
H=ev('https://www.dbi-ag.de/beteiligungen/','Undated older pipeline page asserts Adrecizumab, AB2302 and DB1RA; conflicts with current sold/minority-portfolio structure and does not establish current direct rights.')
cs.append(company('DT.BIOTECH INNOV.AG O.N.',[],[D,H],'Correct issuer website identified as dbi-ag.de. No minority-investee medicines attributed to DBI. Old pipeline claims require primary historical direct-rights reconciliation for AB2302/DB1RA/Adrecizumab; scan remains partial.'))
F=ev('https://www.airtest.com/2023-v1/company','Issuer supplies configured gas sensors for ventilation/building control; 300+ portfolio products do not themselves establish semiconductor-chip manufacturing.')
V=ev('https://www.airtest.com/2023-v1/iaqeye','IAQEye wireless environmental sensor system: HVAC demand-control ventilation, not energy storage or robot.')
cs.append(company('ATI Airtest Technologies Inc',[],[F,V],'Reviewed company and environmental-sensor product portfolio. HVAC energy savings do not make sensors energy storage. Semiconductor sensing-die ownership, any relevant component offerings and older portfolio remain to verify before classifying any product into the four sectors.'))
(out/'batch-0096.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
